<?php $cart=$_SESSION['cart']??[];$subtotal=array_sum(array_map(fn($i)=>$i['price']*$i['quantity'],$cart));$hasProduct=(bool)array_filter($cart,fn($i)=>($i['kind']??'')==='product');$hasTraining=(bool)array_filter($cart,fn($i)=>($i['kind']??'')==='formation');$coupon=$_SESSION['coupon']??null;$discount=$coupon?min($subtotal,$coupon['type']==='percent'?$subtotal*(float)$coupon['value']/100:(float)$coupon['value']):0;$total=$subtotal-$discount;$flash=$_SESSION['flash']??null;unset($_SESSION['flash']); ?>
<section class="checkout-head"><p class="site-kicker"><?= $hasTraining&&!$hasProduct?'VOTRE INSCRIPTION':'VOTRE COMMANDE' ?></p><h1>Votre panier <span><?= count($cart) ?> élément<?= count($cart)>1?'s':'' ?></span></h1></section><?php if($flash): ?><div class="site-flash"><?= htmlspecialchars($flash) ?></div><?php endif ?><?php if(!$cart): ?><section class="cart-empty"><strong>Votre sélection est vide</strong><p>Explorez les formations ou les équipements professionnels.</p><div><a class="site-btn green" href="/formations">Formations</a><a class="site-btn outline" href="/boutique">Boutique</a></div></section><?php else: ?><section class="checkout-layout"><div class="checkout-main"><div class="checkout-box"><div class="box-heading"><h2>Votre sélection</h2><form method="post" action="/panier/vider"><button class="text-danger">Tout retirer</button></form></div><?php foreach($cart as $key=>$item): $training=($item['kind']??'')==='formation'; ?><article class="cart-item"><div class="cart-thumb <?= $training?'navy':'coral' ?>"><?php if(!$training&&!empty($item['image'])): ?><img src="<?= htmlspecialchars($item['image']) ?>" alt=""><?php else: ?>IF<?php endif ?></div><div><span><?= $training?'INSCRIPTION FORMATION':'ARTICLE BOUTIQUE' ?></span><h3><?= htmlspecialchars($item['name']) ?></h3><small><?= $training?'Accès pédagogique nominatif':'Quantité : '.$item['quantity'] ?></small><form method="post" action="/panier/supprimer"><input type="hidden" name="key" value="<?= htmlspecialchars($key) ?>"><button>Supprimer</button></form></div><strong><?= number_format($item['price']*$item['quantity'],0,',',' ') ?> FCFA</strong></article><?php endforeach ?></div></div><aside class="summary-card"><h2>Récapitulatif</h2><p><span>Sous-total</span><b><?= number_format($subtotal,0,',',' ') ?> FCFA</b></p><?php if($discount): ?><p class="discount"><span>Coupon <?= htmlspecialchars($coupon['code']) ?></span><b>− <?= number_format($discount,0,',',' ') ?> F</b></p><?php endif ?><form class="coupon-form" method="post" action="/panier/coupon"><input name="code" placeholder="Code promo" required><button>Appliquer</button></form><hr><p class="total"><span>Total</span><strong><?= number_format($total,0,',',' ') ?> FCFA</strong></p><a class="site-btn gold wide" href="/commande">Continuer vers le paiement →</a></aside></section><?php endif ?>
